    R11 = R11 + R13 , R8 = DM (13,I0);
    NOP;
    NOP;
    /* (inlined .L_wt) */
    I5 = md_shared_scratch_x.;
    I5=MODIFY (I5,0x1F)(NW);
    R1 = R10 - R9;
    R0 = 32;
    R1 = MIN(R1,R0);                     /* samples before the wrap */
    R2 = R0 - R1;
    R3 = LSHIFT R9 BY 2;
    R3 = R3 + R11;
    I4 = R3;
    R6 = DM (I4,M6);
    LCNTR = R1 , DO (PC,.L_wt1_end_i7)UNTIL LCE;
    R6 = LSHIFT R6 BY 8;
    R4 = DM (I1,M2);
    R0 = R6 * R8 (SSF) , DM (I5,M6) = R5;
    R0 = R0 + R4 , R6 = DM (I4,M6);
    R0 = MIN(R0,R14);
.L_wt1_end_i7:
    R5 = MAX(R0,R15);
    R2 = PASS R2;
    IF EQ JUMP .L_wt_done_i7;
    I4 = R11;
    R6 = DM (I4,M6);
    LCNTR = R2 , DO (PC,.L_wt2_end_i7)UNTIL LCE;
    R6 = LSHIFT R6 BY 8;
    R4 = DM (I1,M2);
    R0 = R6 * R8 (SSF) , DM (I5,M6) = R5;
    R0 = R0 + R4 , R6 = DM (I4,M6);
    R0 = MIN(R0,R14);
.L_wt2_end_i7:
    R5 = MAX(R0,R15);
.L_wt_done_i7:
    DM (I5,M6) = R5;
    R0 = 32;
    R9 = R9 + R0;
    COMP (R9,R10);
    JUMP .L_wt_ret_i7 (DB);
    IF GE R9 = R9 - R10;
    NOP;
.L_wt_ret_i7:
    DM (36,I0) = R9;
    I1 = md_shared_scratch_x.;
    I1=MODIFY (I1,0x20)(NW);
    R9 = DM (37,I0);
    R10 = 0x3A;
    R11 = 0x40A200;
    R11 = R11 + R13 , R8 = DM (14,I0);
    NOP;
    NOP;
    /* (inlined .L_wt) */
    I5 = md_shared_scratch_x.;
    I5=MODIFY (I5,0x1F)(NW);
    R1 = R10 - R9;
    R0 = 32;
    R1 = MIN(R1,R0);                     /* samples before the wrap */
    R2 = R0 - R1;
    R3 = LSHIFT R9 BY 2;
    R3 = R3 + R11;
    I4 = R3;
    R6 = DM (I4,M6);
    LCNTR = R1 , DO (PC,.L_wt1_end_i8)UNTIL LCE;
    R6 = LSHIFT R6 BY 8;
    R4 = DM (I1,M2);
    R0 = R6 * R8 (SSF) , DM (I5,M6) = R5;
