    R0 = MIN(R0,R14);
.L_wt1_end_i8:
    R5 = MAX(R0,R15);
    R2 = PASS R2;
    IF EQ JUMP .L_wt_done_i8;
    I4 = R11;
    R6 = DM (I4,M6);
    LCNTR = R2 , DO (PC,.L_wt2_end_i8)UNTIL LCE;
    R6 = LSHIFT R6 BY 8;
    R4 = DM (I1,M2);
    R0 = R6 * R8 (SSF) , DM (I5,M6) = R5;
    R0 = R0 + R4 , R6 = DM (I4,M6);
    R0 = MIN(R0,R14);
.L_wt2_end_i8:
    R5 = MAX(R0,R15);
.L_wt_done_i8:
    DM (I5,M6) = R5;
    R0 = 32;
    R9 = R9 + R0;
    COMP (R9,R10);
    JUMP .L_wt_ret_i8 (DB);
    IF GE R9 = R9 - R10;
    NOP;
.L_wt_ret_i8:
    DM (37,I0) = R9;
    I1 = md_shared_scratch_x.;
