    R9 = DM (38,I0);
    R10 = 0x34;
    R11 = 0x40A300;
    R11 = R11 + R13 , R8 = DM (15,I0);
    NOP;
    NOP;
    /* (inlined .L_wt) */
    I5 = md_shared_scratch_x.;
    I5=MODIFY (I5,0x1F)(NW);
    R1 = R10 - R9;
    R0 = 32;
    R1 = MIN(R1,R0);                     /* samples before the wrap */
    R2 = R0 - R1;
    R3 = LSHIFT R9 BY 2;
    R3 = R3 + R11;
    I4 = R3;
    R6 = DM (I4,M6);
    LCNTR = R1 , DO (PC,.L_wt1_end_i9)UNTIL LCE;
