    I4 = R11;
    R6 = DM (I4,M6);
    LCNTR = R2 , DO (PC,.L_wt2_end_i9)UNTIL LCE;
    R6 = LSHIFT R6 BY 8;
    R4 = DM (I1,M2);
    R0 = R6 * R8 (SSF) , DM (I5,M6) = R5;
    R0 = R0 + R4 , R6 = DM (I4,M6);
