/* ---- biquad pair Y3/Y4, in place over x:$20+k: u(n) = lim(2c u(n-2) +
 * 2g u(n-1) + 2h e(n)), v(n) likewise over u (gen_trx.pair_b_loop). */
    I3 = md_shared_scratch_x.;
    I3=MODIFY (I3,0x20)(NW);
    I5 = md_shared_scratch_x.;
    I5=MODIFY (I5,0x20)(NW);
    I2 = @TMP@;
    R11 = DM (0,I2);
    R12 = DM (1,I2);
    R13 = DM (2,I2);
    R1 = DM (0x16,I0);
    R2 = DM (0x15,I0);
    R3 = DM (0x18,I0);
    R4 = DM (0x17,I0);
    R0 = DM (I3,M6);
    LCNTR = 0x10 , DO (PC,.L_pair_end)UNTIL LCE;
    MRF = R13 * R0 (SSF);
    MRF = MRF + R13 * R0 (SSF);
    MRF = MRF + R11 * R2 (SSF);
    MRF = MRF + R11 * R2 (SSF);
    MRF = MRF + R12 * R1 (SSF);
    MRF = MRF + R12 * R1 (SSF);
    R9 = MR1F;
    R9 = MIN(R9,R14);
    R9 = MAX(R9,R15);
    R2 = PASS R9 , R0 = DM (I3,M6);
    MRF = R13 * R2 (SSF);
    MRF = MRF + R13 * R2 (SSF);
    MRF = MRF + R11 * R4 (SSF);
    MRF = MRF + R11 * R4 (SSF);
    MRF = MRF + R12 * R3 (SSF);
    MRF = MRF + R12 * R3 (SSF);
    R9 = MR1F;
    R9 = MIN(R9,R14);
    R9 = MAX(R9,R15);
    R4 = PASS R9 , DM (I5,M6) = R9;
    MRF = R13 * R0 (SSF);
    MRF = MRF + R13 * R0 (SSF);
    MRF = MRF + R11 * R1 (SSF);
    MRF = MRF + R11 * R1 (SSF);
    MRF = MRF + R12 * R2 (SSF);
    MRF = MRF + R12 * R2 (SSF);
    R9 = MR1F;
    R9 = MIN(R9,R14);
    R9 = MAX(R9,R15);
    R1 = PASS R9 , R0 = DM (I3,M6);
    MRF = R13 * R1 (SSF);
    MRF = MRF + R13 * R1 (SSF);
    MRF = MRF + R11 * R3 (SSF);
    MRF = MRF + R11 * R3 (SSF);
    MRF = MRF + R12 * R4 (SSF);
    MRF = MRF + R12 * R4 (SSF);
    R9 = MR1F;
    R9 = MIN(R9,R14);
    R9 = MAX(R9,R15);
.L_pair_end:
    R3 = PASS R9 , DM (I5,M6) = R9;
    I1 = md_shared_scratch_x.;
    R0 = PASS R1;
    DM (0x16,I0) = R0;
    DM (1,I1) = R0;         /* x:0/1 = u(30), u(31) */
    R0 = PASS R2;
    DM (0x15,I0) = R0;
    DM (0,I1) = R0;         /* x:0/1 = u(30), u(31) */
    R0 = PASS R3;
    DM (0x18,I0) = R0;
    R0 = PASS R4;
    DM (0x17,I0) = R0;

/* ---- highpass biquad Y19.. : x:$20+k -> x:$60+k. Registers (even sample):
 * e(n+1) R1, e(n+2) R2, e(n+1)-e(n) R3, e(n+2)-e(n+1) R4, w(n-1) R5,
 * w(n-2) R6; R11 = c << 8, R12 = g << 8, R13 = 0. */
    I1 = md_shared_scratch_x.;
    I1=MODIFY (I1,0x20)(NW);
    I5 = md_shared_scratch_x.;
    I5=MODIFY (I5,0x60)(NW);
    I2 = @TMP@;
    R11 = DM (4,I2);
    R12 = DM (5,I2);
    R13 = 0;
    R1 = DM (0x1A,I0);
    R0 = DM (0x19,I0);
    R3 = R1 - R0;
    R5 = DM (0x1C,I0);
    R6 = DM (0x1B,I0);
    R2 = DM (I1,M6);
    LCNTR = 0x10 , DO (PC,.L_hp1_end)UNTIL LCE;
    R4 = R2 - R1;
    R0 = R4 - R3;
    MR1F = R0;
    MR0F = R13;
    MRF = MRF + R11 * R6 (SSF);
    MRF = MRF + R11 * R6 (SSF);
    MRF = MRF + R12 * R5 (SSF);
    MRF = MRF + R12 * R5 (SSF);
    R9 = MR1F;
    R9 = MIN(R9,R14);
    R9 = MAX(R9,R15) , R1 = DM (I1,M6);
    R6 = PASS R9 , DM (I5,M6) = R9;
    R3 = R1 - R2;
    R0 = R3 - R4;
    MR1F = R0;
    MR0F = R13;
    MRF = MRF + R11 * R5 (SSF);
    MRF = MRF + R11 * R5 (SSF);
    MRF = MRF + R12 * R6 (SSF);
    MRF = MRF + R12 * R6 (SSF);
    R9 = MR1F;
    R9 = MIN(R9,R14);
    R9 = MAX(R9,R15) , R2 = DM (I1,M6);
.L_hp1_end:
    R5 = PASS R9 , DM (I5,M6) = R9;
    R0 = PASS R5;
    DM (0x1C,I0) = R0;
    R0 = PASS R6;
    DM (0x1B,I0) = R0;
    I1 = md_shared_scratch_x.;
    I1=MODIFY (I1,0x20)(NW);
    R0 = DM (30,I1);
    DM (0x19,I0) = R0;
    R0 = DM (31,I1);
    DM (0x1A,I0) = R0;
    I1 = md_shared_scratch_x.;
    R0 = DM (0x1D,I0);
    DM (0x5E,I1) = R0;
    R0 = DM (0x1E,I0);
    DM (0x5F,I1) = R0;
    R0 = DM (0x1F,I0);
    DM (0x1E,I1) = R0;
    R0 = DM (0x20,I0);
    DM (0x1F,I1) = R0;

/* ---- highpass biquad Y1D.. : x:$60+k -> x:$20+k. Registers (even sample):
 * e(n+1) R1, e(n+2) R2, e(n+1)-e(n) R3, e(n+2)-e(n+1) R4, w(n-1) R5,
 * w(n-2) R6; R11 = c << 8, R12 = g << 8, R13 = 0. */
    I1 = md_shared_scratch_x.;
    I1=MODIFY (I1,0x60)(NW);
    I5 = md_shared_scratch_x.;
    I5=MODIFY (I5,0x20)(NW);
    I2 = @TMP@;
    R11 = DM (8,I2);
    R12 = DM (9,I2);
    R13 = 0;
    R1 = DM (0x1E,I0);
    R0 = DM (0x1D,I0);
    R3 = R1 - R0;
    R5 = DM (0x20,I0);
    R6 = DM (0x1F,I0);
    R2 = DM (I1,M6);
    LCNTR = 0x10 , DO (PC,.L_hp2_end)UNTIL LCE;
    R4 = R2 - R1;
    R0 = R4 - R3;
    MR1F = R0;
    MR0F = R13;
    MRF = MRF + R11 * R6 (SSF);
    MRF = MRF + R11 * R6 (SSF);
    MRF = MRF + R12 * R5 (SSF);
    MRF = MRF + R12 * R5 (SSF);
    R9 = MR1F;
    R9 = MIN(R9,R14);
    R9 = MAX(R9,R15) , R1 = DM (I1,M6);
    R6 = PASS R9 , DM (I5,M6) = R9;
    R3 = R1 - R2;
    R0 = R3 - R4;
    MR1F = R0;
    MR0F = R13;
    MRF = MRF + R11 * R5 (SSF);
    MRF = MRF + R11 * R5 (SSF);
    MRF = MRF + R12 * R6 (SSF);
    MRF = MRF + R12 * R6 (SSF);
    R9 = MR1F;
    R9 = MIN(R9,R14);
    R9 = MAX(R9,R15) , R2 = DM (I1,M6);
.L_hp2_end:
    R5 = PASS R9 , DM (I5,M6) = R9;
    R0 = PASS R5;
    DM (0x20,I0) = R0;
    R0 = PASS R6;
    DM (0x1F,I0) = R0;
    I1 = md_shared_scratch_x.;
    I1=MODIFY (I1,0x60)(NW);
    R0 = DM (30,I1);
    DM (0x1D,I0) = R0;
    R0 = DM (31,I1);
    DM (0x1E,I0) = R0;
    /* y:0..4 = 1/2, -1, 1/2, c, g of the last section */
    I1 = md_shared_scratch_y.;
    I2 = @TMP@;
    R0 = 0x400000;
    DM (0,I1) = R0;
    DM (2,I1) = R0;
    DM (1,I1) = R15;
    R0 = DM (10,I2);
    DM (3,I1) = R0;
    R0 = DM (11,I2);
    DM (4,I1) = R0;

/* ---- block = floor(env * x:$20+k / 2^24) (lim(asr(2*env*x)) never limits) */
    I1 = md_shared_scratch_x.;
    I1=MODIFY (I1,0x20)(NW);
    R0 = 0x9C;
    R1 = I0;
    R0 = R0 + R1;
    I4 = R0;
    R2 = DM (0x10,I0);                  /* env = Y10 */
    R0 = DM (9,I0);
    R0 = PASS R0;
    IF EQ JUMP .L_env_lin;
    R1 = 1;
    R0 = R0 - R1;
    R0 = MAX(R0,R15);
    DM (9,I0) = R0;
    R8 = LSHIFT R2 BY 7;
    LCNTR = 0x20 , DO (PC,.L_hold_end)UNTIL LCE;
    R0 = DM (I1,M6);
    R0 = R0 * R8 (SSF);
.L_hold_end:
    DM (I4,M6) = R0;
    JUMP .L_exit;
.L_env_lin:
    R0 = DM (0xA,I0);
    R0 = PASS R0;
    IF EQ JUMP .L_env_exp;
    R1 = 1;
    R0 = R0 - R1;
    R0 = MAX(R0,R15);
    DM (0xA,I0) = R0;
    R1 = DM (1,I0);
    R3 = PASS R2;
    LCNTR = 0x20 , DO (PC,.L_lin_end)UNTIL LCE;
    R8 = LSHIFT R2 BY 7;
    R0 = DM (I1,M6);
    R0 = R0 * R8 (SSF);
    R3 = R3 - R1;
    R2 = MIN(R3,R14);
    R2 = MAX(R2,R15);
.L_lin_end:
    DM (I4,M6) = R0;
    DM (0x10,I0) = R2;
    JUMP .L_exit;
.L_env_exp:
    R1 = DM (2,I0);
    R1 = LSHIFT R1 BY 8;
    LCNTR = 0x20 , DO (PC,.L_exp_end)UNTIL LCE;
    R8 = LSHIFT R2 BY 7;
    R0 = DM (I1,M6);
    R0 = R0 * R8 (SSF);
    R2 = R1 * R2 (SSF);
    R2 = MIN(R2,R14);
.L_exp_end:
    DM (I4,M6) = R0;
    DM (0x10,I0) = R2;
    JUMP .L_exit;
.L_decline:
    /* tail call: the C reference render runs in this render's place, in
     * its caller's frame (not nested under this one: the audio stack is
     * 509 words) */
    R4 = I0;
    R0 = DM (-11,I6);
    I0 = R0;
    R0 = DM (-12,I6);
    I1 = R0;
    R0 = DM (-13,I6);
    I2 = R0;
    R0 = DM (-14,I6);
    I3 = R0;
    R0 = DM (-15,I6);
    I4 = R0;
    R0 = DM (-16,I6);
    I5 = R0;
    R0 = DM (-17,I6);
    M4 = R0;
    R0 = DM (-18,I6);
    M0 = R0;
    R0 = DM (-19,I6);
    M1 = R0;
    R0 = DM (-20,I6);
    M2 = R0;
    R0 = DM (-21,I6);
    M3 = R0;
    R0 = DM (-23,I6);
    MR1F = R0;
    R0 = DM (-24,I6);
    MR2F = R0;
    R0 = DM (-22,I6);
    MR0F = R0;
    R0 = DM (-46,I6);
    L0 = R0;
    R0 = DM (-47,I6);
    L1 = R0;
    R0 = DM (-48,I6);
    L2 = R0;
    R0 = DM (-49,I6);
    L3 = R0;
    R0 = DM (-50,I6);
    L4 = R0;
    R0 = DM (-51,I6);
    L5 = R0;
    R8 = DM (-3,I6);
    R9 = DM (-4,I6);
    R10 = DM (-5,I6);
    R11 = DM (-6,I6);
    R12 = DM (-7,I6);
    R13 = DM (-8,I6);
    R14 = DM (-9,I6);
    R15 = DM (-10,I6);
    I7=MODIFY (I7,0x34)(NW);
    JUMP trxch_render_block_44k1_c.;
.L_exit:
    R0 = DM (-11,I6);
    I0 = R0;
    R0 = DM (-12,I6);
    I1 = R0;
    R0 = DM (-13,I6);
    I2 = R0;
    R0 = DM (-14,I6);
    I3 = R0;
    R0 = DM (-15,I6);
    I4 = R0;
    R0 = DM (-16,I6);
    I5 = R0;
    R0 = DM (-17,I6);
    M4 = R0;
    R0 = DM (-18,I6);
    M0 = R0;
    R0 = DM (-19,I6);
    M1 = R0;
    R0 = DM (-20,I6);
    M2 = R0;
    R0 = DM (-21,I6);
    M3 = R0;
    R0 = DM (-23,I6);
    MR1F = R0;
    R0 = DM (-24,I6);
    MR2F = R0;
    R0 = DM (-22,I6);
    MR0F = R0;
    R0 = DM (-46,I6);
    L0 = R0;
    R0 = DM (-47,I6);
    L1 = R0;
    R0 = DM (-48,I6);
    L2 = R0;
    R0 = DM (-49,I6);
    L3 = R0;
    R0 = DM (-50,I6);
    L4 = R0;
    R0 = DM (-51,I6);
    L5 = R0;
    R8 = DM (-3,I6);
    R9 = DM (-4,I6);
    R10 = DM (-5,I6);
    R11 = DM (-6,I6);
    R12 = DM (-7,I6);
    R13 = DM (-8,I6);
    R14 = DM (-9,I6);
    R15 = DM (-10,I6);
    I12=DM (M7,I6);
    JUMP (M14,I12) (DB);
    RFRAME;
    NOP;
.ENDSEG;
